from collections import deque
from datetime import datetime, timedelta, time

from QuantConnect import Resolution, DataNormalizationMode, OptionRight
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data.Market import TradeBar


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-1000, 1000)
            .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)

        self._bucket_start = None
        self._bucket_bars = []

        self._entry_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._held_expiration = None
        self._exit_ticket = None
        self._equity_cleanup_ticket = None
        self._entry_block_date = None

    def OnData(self, slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position(current_date)
        self._handle_expiration_processing(current_date)

        if self._held_symbol is not None:
            self._evaluate_held_position(slice, current_date)

        if self._held_symbol is not None:
            return

        if self._entry_ticket is not None:
            return

        if self._entry_block_date == current_date:
            return

        if self.spy not in slice.Bars:
            return

        completed_bar = self._aggregate_minute_bar(slice.Bars[self.spy])
        if completed_bar is None:
            return

        self.fast_window.append(completed_bar.Close)
        self.slow_window.append(completed_bar.Close)

        if len(self.fast_window) < 20:
            return

        fast_current = sum(list(self.fast_window)[-5:]) / 5.0
        slow_current = sum(self.slow_window) / 20.0

        # The preceding averages are represented by the windows before
        # appending the current completed five-minute bar.
        previous_fast_window = list(self.fast_window)[:-1]
        previous_slow_window = list(self.slow_window)[:-1]

        if len(previous_fast_window) < 5 or len(previous_slow_window) < 20:
            return

        fast_previous = sum(previous_fast_window[-5:]) / 5.0
        slow_previous = sum(previous_slow_window[-20:]) / 20.0

        end_time = completed_bar.EndTime.time()
        if not (time(9, 45) <= end_time <= time(14, 30)):
            return

        if fast_previous <= slow_previous and fast_current > slow_current:
            self._try_enter(slice, completed_bar.Close, current_date)

    def OnOrderEvent(self, order_event):
        if self._entry_ticket is not None:
            if order_event.OrderId == self._entry_ticket.OrderId:
                if order_event.Status == order_event.Status.Filled:
                    self._held_symbol = order_event.Symbol
                    self._entry_price = order_event.FillPrice
                    security = self.Securities[order_event.Symbol]
                    self._held_expiration = security.Symbol.ID.Date.date()

                    self.Debug(
                        f"ENTRY {order_event.Symbol} "
                        f"fill={order_event.FillPrice:.4f}"
                    )
                    self._entry_ticket = None

                elif order_event.Status in (
                    order_event.Status.Canceled,
                    order_event.Status.Invalid,
                    order_event.Status.Submitted,
                ):
                    if order_event.Status in (
                        order_event.Status.Canceled,
                        order_event.Status.Invalid,
                    ):
                        self._entry_ticket = None
                return

        if self._exit_ticket is not None:
            if order_event.OrderId == self._exit_ticket.OrderId:
                if order_event.Status == order_event.Status.Filled:
                    self.Debug(f"EXIT {order_event.Symbol}")
                    self._clear_position_state()
                    self._exit_ticket = None
                elif order_event.Status in (
                    order_event.Status.Canceled,
                    order_event.Status.Invalid,
                ):
                    self._exit_ticket = None
                return

        if self._equity_cleanup_ticket is not None:
            if order_event.OrderId == self._equity_cleanup_ticket.OrderId:
                if order_event.Status in (
                    order_event.Status.Filled,
                    order_event.Status.Canceled,
                    order_event.Status.Invalid,
                ):
                    self._equity_cleanup_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug(f"UNEXPECTED ASSIGNMENT {order_event.Symbol}")

    def _aggregate_minute_bar(self, minute_bar):
        start = minute_bar.Time

        if start.tzinfo is not None:
            start = start.replace(tzinfo=None)

        if start.time() < time(9, 30) or start.time() >= time(16, 0):
            return None

        bucket_start = start.replace(
            minute=(start.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self._bucket_start != bucket_start:
            self._bucket_start = bucket_start
            self._bucket_bars = []

        expected_start = bucket_start + timedelta(minutes=len(self._bucket_bars))

        if start != expected_start:
            self._bucket_bars = []
            self._bucket_start = bucket_start
            expected_start = bucket_start

        if start != expected_start:
            return None

        self._bucket_bars.append(minute_bar)

        if len(self._bucket_bars) != 5:
            return None

        bars = self._bucket_bars
        self._bucket_bars = []

        return TradeBar(
            bucket_start,
            self.spy,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

    def _try_enter(self, slice, spy_price, current_date):
        chain = None

        for candidate_chain in slice.OptionChains.Values:
            if candidate_chain.Symbol == self.option_symbol:
                chain = candidate_chain
                break

        if chain is None:
            self.Debug("SKIP entry: no option chain")
            return

        eligible = []
        for contract in chain:
            expiration_date = contract.Expiry.date()
            days_to_expiration = (expiration_date - current_date).days

            if (
                days_to_expiration >= 7
                and contract.Right == OptionRight.Call
            ):
                eligible.append(contract)

        if not eligible:
            self.Debug("SKIP entry: no eligible expiration or call")
            return

        nearest_expiration = min(
            contract.Expiry.date() for contract in eligible
        )

        strike_floor = 1.01 * spy_price
        candidates = [
            contract for contract in eligible
            if (
                contract.Expiry.date() == nearest_expiration
                and contract.Strike >= strike_floor
            )
        ]

        if not candidates:
            self.Debug("SKIP entry: no call at required strike")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover"
        )

    def _evaluate_held_position(self, slice, current_date):
        if self._held_expiration is None:
            return

        if (
            current_date == self._held_expiration - timedelta(days=1)
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration-eve time stop")
            return

        if self._held_symbol not in self.Securities:
            return

        quote = None
        for chain in slice.OptionChains.Values:
            if self._held_symbol in chain.Contracts:
                quote = chain.Contracts[self._held_symbol]
                break

        if quote is None:
            return

        bid = quote.BidPrice
        ask = quote.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self._entry_price is not None and midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50 percent profit target")

    def _handle_expiration_processing(self, current_date):
        if (
            self._held_symbol is not None
            and self._held_expiration is not None
            and current_date >= self._held_expiration
        ):
            self._entry_block_date = current_date
            self._submit_exit("expiration processing safeguard")

    def _submit_exit(self, reason):
        if self._held_symbol is None or self._exit_ticket is not None:
            return

        self.Transactions.CancelOpenOrders(self._held_symbol)

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            self._clear_position_state()
            return

        self.Debug(f"EXIT {self._held_symbol}: {reason}")
        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -abs(quantity),
            tag=reason
        )

    def _handle_unexpected_spy_position(self, current_date):
        holding = self.Portfolio[self.spy]

        if holding.Quantity == 0 or self._equity_cleanup_ticket is not None:
            return

        self._entry_block_date = current_date
        self.Debug("UNEXPECTED EXERCISE/ASSIGNMENT: liquidating SPY equity")
        self._equity_cleanup_ticket = self.MarketOrder(
            self.spy,
            -holding.Quantity,
            tag="Unexpected exercise or assignment cleanup"
        )

    def _clear_position_state(self):
        self._held_symbol = None
        self._entry_price = None
        self._held_expiration = None

