from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyFiveMinuteCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.no_entry_today = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.no_entry_today is False:
            self.no_entry_today = False

        self._liquidate_unexpected_equity_position()

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            self._process_held_option(slice, current_date)

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is None:
            return

        self._process_minute_bar(spy_bar, slice, current_date)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice, current_date):
        end_time = bar.EndTime.replace(second=0, microsecond=0)

        if end_time.date() != current_date:
            return

        if end_time.hour < 9 or end_time.hour > 16:
            return

        if end_time.hour == 9 and end_time.minute < 31:
            return

        if end_time.hour == 16 and end_time.minute > 0:
            return

        minute_index = ((end_time.hour * 60) + end_time.minute - 1) // 5
        bucket_end_minutes = (minute_index + 1) * 5
        bucket_end = end_time.replace(
            hour=bucket_end_minutes // 60,
            minute=bucket_end_minutes % 60
        )

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[end_time] = bar

        if end_time != bucket_end:
            return

        expected_times = [
            bucket_end - timedelta(minutes=i) for i in range(4, -1, -1)
        ]

        if any(t not in self.bucket_bars for t in expected_times):
            self.bucket_bars = {}
            return

        five_minute_bar = self.bucket_bars[bucket_end]
        close = five_minute_bar.Close

        if len(self.slow_window) == 20:
            self.previous_fast = sum(list(self.fast_window)[-5:]) / 5.0
            self.previous_slow = sum(self.slow_window) / 20.0

        self.fast_window.append(close)
        self.slow_window.append(close)

        current_fast = None
        current_slow = None

        if len(self.fast_window) == 5:
            current_fast = sum(self.fast_window) / 5.0
        if len(self.slow_window) == 20:
            current_slow = sum(self.slow_window) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        eligible_time = (
            bucket_end.hour > 9 or
            (bucket_end.hour == 9 and bucket_end.minute >= 45)
        ) and (
            bucket_end.hour < 14 or
            (bucket_end.hour == 14 and bucket_end.minute <= 30)
        )

        if bullish_cross and eligible_time:
            self._try_enter(slice, close, current_date)

        self.bucket_bars = {}

    def _try_enter(self, slice: Slice, spy_price: float, current_date):
        if self.no_entry_today:
            return

        if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
            return

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            return

        contracts = []

        if slice.OptionChains:
            for chain in slice.OptionChains.Values:
                for contract in chain.Contracts.Values:
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug("Skipped call selection: no expiration at least 7 days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call contract.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(self.entry_symbol, 1)

        self.Debug(
            "Call entry submitted: {0}, expiry {1}, strike {2}".format(
                self.entry_symbol, selected_expiry, selected.Strike
            )
        )

    def _process_held_option(self, slice: Slice, current_date):
        symbol = self.entry_symbol
        if symbol is None or not self.Portfolio[symbol].Invested:
            return

        expiry_date = symbol.ID.Date.date()

        if current_date >= expiry_date:
            self.no_entry_today = True
            self._submit_exit("expiration processing")
            return

        if (
            self.Time.hour == 15
            and self.Time.minute == 45
            and self._is_immediately_preceding_trading_day(
                current_date, expiry_date
            )
        ):
            self._submit_exit("expiration time stop")
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            return

        option_contract = None

        if slice.OptionChains:
