        self._process_minute_bar(spy_bar, slice, current_date)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice, current_date):
        end_time = bar.EndTime.replace(second=0, microsecond=0)

        if end_time.date() != current_date:
            return

        if end_time.hour < 9 or end_time.hour > 16:
