        if self.bucket_end != bucket_end:
            self.bucket_date = end_time.date()
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[end_time] = minute_bar

        if end_time.minute % 5 != 0 or end_time.second != 0:
            return

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        valid = (
            len(self.bucket_bars) == 5
            and all(t in self.bucket_bars for t in expected_times)
        )

        if valid:
            close_price = float(self.bucket_bars[expected_times[-1]].Close)
            self._process_five_minute_close(bucket_end, close_price, data)

        self.bucket_bars = {}
        self.bucket_end = None

    def _process_five_minute_close(self, bar_end, close_price, data):
        self.fast_values.append(close_price)
        self.slow_values.append(close_price)

        if len(self.fast_values) > 5:
            self.fast_values.pop(0)
        if len(self.slow_values) > 20:
            self.slow_values.pop(0)

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        fast_current = sum(self.fast_values[-5:]) / 5.0
        slow_current = sum(self.slow_values[-20:]) / 20.0

        if len(self.fast_values) < 6 or len(self.slow_values) < 21:
            return

        fast_previous = sum(self.fast_values[-6:-1]) / 5.0
        slow_previous = sum(self.slow_values[-21:-1]) / 20.0

        bar_time = bar_end.time()
        eligible_start = datetime.strptime("09:45", "%H:%M").time()
        eligible_end = datetime.strptime("14:30", "%H:%M").time()

        bullish_cross = (
            fast_previous <= slow_previous
            and fast_current > slow_current
        )

        if not (
            bullish_cross
            and eligible_start <= bar_time <= eligible_end
            and self.expiration_processing_date != bar_end.date()
            and self.held_symbol is None
            and not self._entry_order_is_open()
        ):
            return

        spy_price = close_price
        selected = self._select_option(data, spy_price, bar_end.date())

        if selected is None:
            self.Debug("Skipped call selection: no eligible contract.")
            return

        self.entry_symbol = selected
        self.entry_ticket = self.MarketOrder(
            selected,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.Debug("Call entry submitted: " + str(selected))

    def _select_option(self, data, spy_price, algorithm_date):
        chains = []

        if data.OptionChains:
            for chain in data.OptionChains.Values:
                chains.append(chain)

        if not chains:
            return None

        minimum_expiry = algorithm_date + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if (
                    contract.Right == OptionRight.Call
                    and expiry_date >= minimum_expiry
                ):
                    candidates.append(contract)

        if not candidates:
            return None

        nearest_expiry = min(c.Expiry.date() for c in candidates)
        strike_floor = spy_price * 1.01

        strike_candidates = [
            c for c in candidates
            if c.Expiry.date() == nearest_expiry
            and c.Strike >= strike_floor
        ]

        if not strike_candidates:
            return None

        selected = min(
            strike_candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )
        return selected.Symbol

    def _update_open_position_exit(self, data, current_date):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested or holding.Quantity <= 0:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if (
            current_date == expiry_date
            and self.expiration_processing_date != current_date
        ):
            self._liquidate_option("expiration-day liquidation")
            self.expiration_processing_date = current_date
            return

        if (
            current_date == expiry_date - timedelta(days=1)
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._liquidate_option("pre-expiration time stop")
            return

        if self._exit_order_is_open():
            return

        quote = self._find_option_quote(data, self.held_symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._liquidate_option("50 percent profit target")

    def _find_option_quote(self, data, symbol):
        if not data.OptionChains:
            return None

        for chain in data.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return float(contract.BidPrice), float(contract.AskPrice)

        return None

    def _liquidate_option(self, reason):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = int(holding.Quantity)

        if quantity <= 0:
            return

        if self._exit_order_is_open():
            self.exit_ticket.Cancel("Replacing with liquidation market order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Call exit submitted: " + reason)

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_ticket = None
                self.Debug(
                    "Call entry filled at " + str(self.entry_price)
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.entry_ticket = None
                self.entry_symbol = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Call exit filled.")
            self.exit_ticket = None
            self.held_symbol = None
            self.entry_price = None
            self.entry_symbol = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.assignment_processing_date = self.Time.date()
        self.Debug("Unexpected option exercise or assignment handled.")

        if self.Portfolio[self.spy].Quantity != 0:
            quantity = int(self.Portfolio[self.spy].Quantity)
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Liquidate unexpected assignment equity"
            )

    def _handle_unexpected_equity_position(self, current_date):
        holding = self.Portfolio[self.spy]
        if holding.Quantity == 0:
            return

        if self.assignment_processing_date != current_date:
            self.Debug("Unexpected SPY equity position liquidated.")
            self.assignment_processing_date = current_date

        self.MarketOrder(
            self.spy,
            -int(holding.Quantity),
            tag="Liquidate unexpected SPY equity"
        )

    def _handle_expiration_processing(self, current_date):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        if current_date >= expiry_date:
            if self.expiration_processing_date != current_date:
                self._liquidate_option("expiration processing liquidation")
                self.expiration_processing_date = current_date

    def _entry_order_is_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _exit_order_is_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

