        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.no_entries_today = False

    def OnData(self, slice: Slice):
        self._handle_unexpected_equity_position()

        if self.held_symbol is not None:
            self._evaluate_exit(slice)

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        end_time = minute_bar.EndTime.replace(second=0, microsecond=0)
        minutes = end_time.hour * 60 + end_time.minute
        bucket_minutes = ((minutes + 4) // 5) * 5
        bucket_end = end_time.replace(hour=0, minute=0) + timedelta(
            minutes=bucket_minutes
        )

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self._finish_bucket(self.bucket_end, slice)

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[end_time] = minute_bar

    def _finish_bucket(self, bucket_end, slice: Slice):
        bars = self.bucket_bars
        self.bucket_end = None
        self.bucket_bars = {}

        if len(bars) != 5:
            return

        expected = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if any(t not in bars for t in expected):
            return

        first = bars[expected[0]]
        last = bars[expected[-1]]

        if first.EndTime.time() < datetime.time(9, 31):
            return
        if bucket_end.time() > datetime.time(16, 0):
            return

        close = float(last.Close)
        self.closes.append(close)

        if len(self.closes) > self.slow_period + 1:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period + 1:
            return

        previous = self.closes[:-1]
        current = self.closes

        previous_fast = sum(previous[-self.fast_period:]) / self.fast_period
        previous_slow = sum(previous[-self.slow_period:]) / self.slow_period
        current_fast = sum(current[-self.fast_period:]) / self.fast_period
        current_slow = sum(current[-self.slow_period:]) / self.slow_period

        bullish = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_end_time = bucket_end
        eligible_time = (
            datetime.time(9, 45) <= bar_end_time.time() <= datetime.time(14, 30)
        )

        if bullish and eligible_time:
            self._attempt_entry(slice, close)

    def _attempt_entry(self, slice: Slice, spy_price: float):
        if self.no_entries_today:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self._ticket_closed(
            self.entry_ticket
        ):
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiration = current_date + timedelta(days=7)

        contracts = list(chain.Contracts.Values)
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped call selection: no valid expiration.")
            return

        expiration = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call.")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Call entry submitted: " + str(selected.Symbol))

    def _evaluate_exit(self, slice: Slice):
