            return

        holding = self.Portfolio[self.held_symbol]
        if holding.Quantity <= 0:
            return

        if self.expiration_date is not None:
            if self.Time.date() >= self.expiration_date:
                self.no_entries_today = True
                self._submit_exit("expiration processing")
                return

            previous_trading_day = self._previous_trading_day(
                self.expiration_date
            )

            if (
                self.Time.date() == previous_trading_day
                and self.Time.time() >= datetime.time(15, 45)
            ):
                self._submit_exit("expiration time stop")
                return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return

        contract = chain.Contracts.get(self.held_symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if (
            self.entry_price is not None
            and midpoint >= 1.50 * self.entry_price
        ):
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = int(holding.Quantity)

        if quantity <= 0:
            return

        if self.exit_ticket is not None and not self._ticket_closed(
            self.exit_ticket
        ):
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Call exit submitted: " + reason)

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_ticket.Symbol
                self.entry_price = float(self.entry_ticket.AverageFillPrice)
                self.expiration_date = self.held_symbol.ID.Date.date()
                self.Debug(
                    "Call entry filled: "
                    + str(self.held_symbol)
                    + " @ "
                    + str(self.entry_price)
                )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Call exit filled.")
            self.held_symbol = None
            self.entry_price = None
            self.expiration_date = None
            self.exit_ticket = None

        self._handle_unexpected_equity_position()

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.no_entries_today = True
        self.Debug("Unexpected option exercise or assignment handled.")
        self._handle_unexpected_equity_position()

    def _handle_unexpected_equity_position(self):
        quantity = int(self.Portfolio[self.spy.Symbol].Quantity)

        if quantity != 0:
            self.no_entries_today = True
            self.Debug("Unexpected SPY equity position liquidated.")
            self.MarketOrder(self.spy.Symbol, -quantity, tag="assignment handling")

    def _previous_trading_day(self, date_value):
        date_value = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)

        return date_value

    @staticmethod
    def _ticket_closed(ticket):
        return ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        )

