from AlgorithmImports import *
from datetime import datetime, timedelta
from collections import defaultdict


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 400)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = RollingWindow[float](self.slow_period)

        self.minute_bars = {}
        self.current_bucket = None

        self.option_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.expiration_date = None
        self.time_stop_date = None
        self.no_entry_date = None
        self.exercise_liquidation_submitted = False

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.option_symbol is not None and self.expiration_date is not None:
            if today >= self.expiration_date:
                self.no_entry_date = today
                if self.Portfolio[self.option_symbol].Invested:
                    self._submit_exit("expiration processing")
            elif today == self.time_stop_date and self.Time.hour == 15 and self.Time.minute >= 45:
                if self.Portfolio[self.option_symbol].Invested:
                    self._submit_exit("pre-expiration time stop")

        self._handle_unexpected_equity_position()
        self._evaluate_profit_target(slice)

        if not slice.Bars.ContainsKey(self.spy.Symbol):
            return

        bar = slice.Bars[self.spy.Symbol]
        local_time = self.Time.replace(second=0, microsecond=0)

        if local_time.hour < 9 or local_time.hour >= 16:
            return

        if local_time.hour == 9 and local_time.minute < 30:
            return

        bucket_start = local_time.replace(
            minute=(local_time.minute // 5) * 5
        )
        bucket_key = (bucket_start.date(), bucket_start.hour, bucket_start.minute)

        if self.current_bucket != bucket_key:
            self.minute_bars = {}
            self.current_bucket = bucket_key

        self.minute_bars[local_time] = bar

        if local_time.minute % 5 != 4:
            return

        expected_times = [
            bucket_start + timedelta(minutes=i) for i in range(5)
        ]

        if any(t not in self.minute_bars for t in expected_times):
            self.Debug(
                "Skipped incomplete SPY five-minute bar ending "
                + str(bucket_start + timedelta(minutes=5))
            )
            self.minute_bars = {}
            return

        bars = [self.minute_bars[t] for t in expected_times]
        self.minute_bars = {}

        consolidated_close = bars[-1].Close
        previous_fast = None
        previous_slow = None

        if self.closes.Count >= self.slow_period:
            previous_fast = sum(
                self.closes[i] for i in range(self.fast_period)
            ) / self.fast_period
            previous_slow = sum(
                self.closes[i] for i in range(self.slow_period)
            ) / self.slow_period

        self.closes.Add(consolidated_close)

        if self.closes.Count < self.slow_period:
            return

        current_fast = sum(
            self.closes[i] for i in range(self.fast_period)
        ) / self.fast_period
        current_slow = sum(
            self.closes[i] for i in range(self.slow_period)
        ) / self.slow_period

        bar_end = bucket_start + timedelta(minutes=5)
        eligible_time = (
            bar_end.hour > 9 or
            (bar_end.hour == 9 and bar_end.minute >= 45)
        ) and (
            bar_end.hour < 14 or
            (bar_end.hour == 14 and bar_end.minute <= 30)
        )

        bullish_crossover = (
            previous_fast is not None and
            previous_slow is not None and
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if eligible_time and bullish_crossover:
            self._evaluate_entry(slice, today)

    def _evaluate_entry(self, slice: Slice, algorithm_date):
        if self.no_entry_date == algorithm_date:
            return

        if self.option_symbol is not None and self.Portfolio[self.option_symbol].Invested:
            return

        if self._order_is_open(self.entry_ticket):
            return

        if not slice.OptionChains:
            self.Debug("Skipped entry: no option chain in current Slice")
            return

        current_price = self.Securities[self.spy.Symbol].Price
        if current_price <= 0:
            self.Debug("Skipped entry: invalid SPY price")
            return

        eligible_contracts = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue

                expiration_date = contract.Expiry.date()
                days_to_expiration = (expiration_date - algorithm_date).days

                if days_to_expiration >= 7:
                    eligible_contracts.append(contract)

        if not eligible_contracts:
            self.Debug("Skipped entry: no expiration at least seven days away")
            return

        selected_expiration = min(
            contract.Expiry.date() for contract in eligible_contracts
        )

        strike_floor = 1.01 * current_price
        candidates = [
            contract for contract in eligible_contracts
            if contract.Expiry.date() == selected_expiration
            and contract.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.option_symbol = selected.Symbol
        self.expiration_date = selected.Expiry.date()
        self.time_stop_date = self._previous_trading_day(self.expiration_date)
        self.entry_price = None

        self.entry_ticket = self.MarketOrder(
            self.option_symbol,
            1,
            tag="SPY bullish five-minute crossover entry"
        )

        self.Debug("Entry submitted: " + str(self.option_symbol))

    def _evaluate_profit_target(self, slice: Slice):
        if self.option_symbol is None:
            return

        holding = self.Portfolio[self.option_symbol]
        if not holding.Invested or self.entry_price is None:
            return

        if self._order_is_open(self.exit_ticket):
            return

        if not slice.QuoteBars.ContainsKey(self.option_symbol):
            return

        quote = slice.QuoteBars[self.option_symbol]
        bid = quote.Bid.Close if quote.Bid is not None else 0
        ask = quote.Ask.Close if quote.Ask is not None else 0

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.option_symbol is None:
            return

        if self._order_is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.option_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.option_symbol,
            -quantity,
            tag="SPY call exit: " + reason
        )

        self.Debug("Exit submitted: " + reason)

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: " + str(self.option_symbol) +
                    " at " + str(self.entry_price)
                )
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order canceled or invalid")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: " + str(self.option_symbol))
                self.exit_ticket = None
                self.option_symbol = None
                self.entry_price = None
                self.expiration_date = None
                self.time_stop_date = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        is_assignment = getattr(order_event, "IsAssignment", False)
        is_exercise = getattr(order_event, "IsExercise", False)

        if is_assignment or is_exercise:
            self.Debug("Unexpected option exercise or assignment handling")
            self._handle_unexpected_equity_position()

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity

        if quantity != 0 and not self.exercise_liquidation_submitted:
            self.Debug("Unexpected SPY equity position; liquidating immediately")
            self.MarketOrder(
                self.spy.Symbol,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
            self.exercise_liquidation_submitted = True
        elif quantity == 0:
            self.exercise_liquidation_submitted = False

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while True:
            candidate_dt = datetime(
                candidate.year,
                candidate.month,
                candidate.day
            )

            if self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(candidate_dt):
                return candidate

            candidate -= timedelta(days=1)

    def _order_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

